function dhanEntryAlertPrice(entry){return Math.round(Number(entry)*1.02*100)/100;}
function updateDhanAlertPreview(){const entry=Number($('entry').value),level=entry>0?dhanEntryAlertPrice(entry):0;$('dhanAlertLevel').textContent=level?money(level):'Enter Entry first';$('copyDhanAlertPrice').disabled=!level;$('copyDhanAlertPrice').dataset.price=level?String(level):'';}
function updateCalculation(){
 $('plannerDefaults').textContent=`Capital ${money(state.settings.capital)} / Risk ${state.settings.risk}% (${money(state.settings.capital*state.settings.risk/100)} per trade) / Default R:R 1:${state.settings.rr}`;
 const e=+$('entry').value,s=+$('sl').value;targetManual=$('targetMode').value==='manual';
 if(!targetManual)$('target').value=e>s&&s>0?(e+(e-s)*state.settings.rr).toFixed(2):'';
 const automatic=calc(e,s,+$('target').value),manualQty=$('qtyMode').value==='manual',manualFee=$('brokerageMode').value==='manual';
 if(!manualQty)$('planQty').value=automatic.qty;
 if(!manualFee)$('planBrokerage').value='0.00';
 $('target').readOnly=!targetManual;$('planQty').readOnly=!manualQty;$('planBrokerage').readOnly=!manualFee;
 const qty=+$('planQty').value,profit=qty*(+$('target').value-e),risk=qty*(e-s),cost=qty*e;
 $('calculation').innerHTML=`<div class="row"><span>Quantity / ${manualQty?'Manual':'Auto'}</span><strong>${qty} shares</strong></div><div class="row"><span>Planned price risk</span><b class="red">${money(risk||0)}</b></div><div class="row"><span>Potential profit before charges</span><b class="green">${money(profit||0)}</b></div><div class="row"><span>Actual risk / reward</span><b>1:${Number.isFinite(automatic.rr)?automatic.rr.toFixed(2):'--'}</b></div><div class="row"><span>Capital required</span><b>${money(cost||0)}</b></div><div class="row"><span>Suggested automatic quantity</span><b>${automatic.qty}</b></div>`;
 updateDhanAlertPreview();
}
for(const id of ['entry','sl','target','planQty','planBrokerage'])$(id).addEventListener('input',()=>{if(id==='target')$('targetMode').value='manual';updateCalculation();});
for(const id of ['targetMode','qtyMode','brokerageMode'])$(id).onchange=updateCalculation;
$('copyDhanAlertPrice').onclick=async()=>{const price=$('copyDhanAlertPrice').dataset.price;if(!price)return;try{await navigator.clipboard.writeText(price);toast(`Dhan price alert level ${money(Number(price))} copied. Set it manually in Dhan.`);}catch{toast('Could not copy. Use the displayed Dhan alert level and enter it in Dhan manually.');}};
$('resetTarget').onclick=()=>{$('targetMode').value='auto';updateCalculation();};
$('resetAllAuto').onclick=()=>{for(const id of ['targetMode','qtyMode','brokerageMode'])$(id).value='auto';updateCalculation();};
function clearForm(){editing=null;targetManual=false;autoSectorSuggestion='';$('planform').reset();for(const id of ['targetMode','qtyMode','brokerageMode'])$(id).value='auto';$('formTitle').textContent='Create a trade plan';updateCalculation();}
$('cancelEdit').onclick=clearForm;$('newtrade').onclick=()=>{clearForm();page('planner');};
$('symbol').addEventListener('input',()=>{const field=$('sectorIndex'),suggestion=sectorIndexFor($('symbol').value);if(!field.value||field.value.trim().toUpperCase()===autoSectorSuggestion){field.value=suggestion;autoSectorSuggestion=suggestion;}});
$('sectorIndex').addEventListener('input',()=>{if($('sectorIndex').value.trim().toUpperCase()!==autoSectorSuggestion)autoSectorSuggestion='';});
 $('planform').onsubmit=e=>{e.preventDefault();const old=state.plans.find(p=>p.id===editing),symbol=$('symbol').value.trim().toUpperCase();if(old&&old.status!=='Watching')return toast('Disarm first. Holding and closed trades cannot be edited in this preview.');const p={id:editing||uid(),setup:$('setup').value.trim(),symbol,sectorIndex:$('sectorIndex').value.trim().toUpperCase()||sectorIndexFor(symbol),timeframe:$('timeframe').value,entry:+$('entry').value,sl:+$('sl').value,target:+$('target').value,cmp:old?.cmpSource==='Dhan'?old.cmp:null,cmpSource:old?.cmpSource||'Awaiting Dhan',targetMode:$('targetMode').value==='manual'?'manual':'auto',qtyMode:$('qtyMode').value==='manual'?'manual':'auto',brokerageMode:$('brokerageMode').value==='manual'?'manual':'auto',manualBrokerage:+$('planBrokerage').value,expiry:$('expiry').value,notes:$('notes').value,status:'Watching'};p.qty=p.qtyMode==='manual'?+$('planQty').value:calc(p.entry,p.sl,p.target).qty;TradeMath.derive(p,state.settings);const error=valid(p);if(error)return toast(error);if(state.plans.some(x=>x.id!==p.id&&TradeImport.key(x)===TradeImport.key(p)))return toast('This exact setup already exists. Edit it or use a different entry/setup.');if(old){if(old.entry!==p.entry)for(const key of ['telegramEntryAlertSentAt','telegramEntryAlertAttemptAt','telegramEntryAlertMessageId','telegramEntryAlertError'])delete old[key];Object.assign(old,p);}else state.plans.push(p);clearForm();save();toast('Trade plan saved as Watching. Telegram will alert once CMP enters 2% of Entry if Dhan CMP and Telegram are connected.');};
async function telegramStatus(){try{const r=await fetch('/api/telegram/status',{cache:'no-store'}),d=await r.json();if(d.chatId&&!$('telegramChatId').value)$('telegramChatId').value=d.chatId;$('telegramStatus').textContent=d.error?`Saved Telegram settings could not be unlocked: ${d.error}`:d.configured?`Telegram ready for group ${d.chatId}. Bot token is saved encrypted; the password field stays blank for security.`:d.tokenSaved?'Bot token is saved encrypted. The group ID is missing; find and save it once. You will not need to re-enter the token.': 'Telegram is not configured on this Windows account. Enter the bot token and group ID once; they will be saved encrypted for future app starts.';}catch{$('telegramStatus').textContent='Telegram settings unavailable. Start the local backend.';}}
async function sharePlanTelegram(p){
 const esc=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
 const risk=Number(p.qty||0)*(Number(p.entry)-Number(p.sl)),profit=Number(p.qty||0)*(Number(p.target)-Number(p.entry)),rr=(p.target-p.entry)/(p.entry-p.sl);
 const caption=`<b>NEW TRADE PLAN — ${esc(p.symbol)}</b>\n<b>Side:</b> BUY · <b>Product:</b> CNC Delivery\n<b>Setup / zone:</b> ${esc(p.setup||'—')} · <b>Execution:</b> ${esc(p.timeframe||'—')}\n<b>Entry:</b> ${money(p.entry)}\n<b>Stop-loss:</b> ${money(p.sl)}\n<b>Target:</b> ${money(p.target)}\n<b>Quantity:</b> ${Number(p.qty||0)} shares\n<b>Planned risk:</b> ${money(risk)}\n<b>Potential profit:</b> ${money(profit)}\n<b>R:R:</b> 1:${Number.isFinite(rr)?rr.toFixed(2):'—'}${p.notes?`\n<b>Note:</b> ${esc(p.notes).slice(0,350)}`:''}\n\n<i>Plan only — order not placed.</i>`;
 const ready=await fetch('/api/telegram/status',{cache:'no-store'}).then(r=>r.json()).catch(()=>null);if(!ready?.configured)return toast('Configure the Telegram bot and group chat ID in Settings first.');
 const picker=document.createElement('input');picker.type='file';picker.accept='image/png,image/jpeg';picker.onchange=async()=>{const file=picker.files?.[0];if(!file)return;if(file.size>5_000_000)return toast('Choose a PNG/JPEG screenshot under 5 MB.');if(!['image/png','image/jpeg'].includes(file.type))return toast('Choose a PNG or JPEG chart screenshot.');if(!window.confirm('Send this trade plan and screenshot to the configured Telegram group?\n\n'+caption.replace(/<[^>]*>/g,'')))return;try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read screenshot.'));reader.readAsDataURL(file);});const response=await fetch('/api/telegram/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({caption,image:base64,filename:file.name}),signal:AbortSignal.timeout(30000)});const result=await response.json().catch(()=>({error:'The app server returned an invalid response. Confirm Deep Trading Desk is running on port 8081 and refresh the page.'}));if(!response.ok)throw Error(result.error||'Telegram send failed.');toast(`${p.symbol} plan and screenshot sent to Telegram.`);}catch(error){toast(error.message||'Telegram send failed.');}};picker.click();
}
const telegramEntryAlertsInFlight=new Set();
function entryZoneAlertImage(p,crossed=false){return new Promise((resolve,reject)=>{const canvas=document.createElement('canvas');canvas.width=1120;canvas.height=660;const c=canvas.getContext('2d');if(!c)return reject(Error('Could not prepare the Telegram alert image.'));c.fillStyle='#0c1422';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#12243a';c.fillRect(0,0,canvas.width,118);c.fillStyle='#45d2aa';c.fillRect(0,0,12,canvas.height);c.fillStyle='#f2f6fc';c.font='700 34px Segoe UI, Arial';c.fillText('DEEP TRADING DESK',48,56);c.fillStyle='#aabbd0';c.font='20px Segoe UI, Arial';c.fillText(crossed?'ENTRY ZONE CROSSED BETWEEN QUOTE CHECKS':'ENTRY ZONE ALERT · CMP WITHIN 2% OF ENTRY',48,91);c.fillStyle='#f2f6fc';c.font='700 46px Segoe UI, Arial';c.fillText(String(p.symbol||'').toUpperCase(),48,184);c.fillStyle='#aabbd0';c.font='22px Segoe UI, Arial';c.fillText(`${p.setup||'Setup not set'}  ·  ${p.timeframe||'Timeframe not set'}  ·  NSE / DELIVERY`,48,222);const box=(x,y,w,label,value,color)=>{c.fillStyle='#142235';c.beginPath();c.roundRect(x,y,w,142,14);c.fill();c.fillStyle='#9fb1c8';c.font='18px Segoe UI, Arial';c.fillText(label,x+22,y+42);c.fillStyle=color;c.font='700 30px Segoe UI, Arial';c.fillText(value,x+22,y+94);};box(48,260,320,'DHAN CMP',money(p.cmp),'#f2f6fc');box(400,260,320,'PLANNED ENTRY',money(p.entry),'#61a4ff');box(752,260,320,'DISTANCE',`${distance(p).toFixed(2)}%`,'#f5c16c');box(48,430,320,'STOP-LOSS',money(p.sl),'#ff7c8a');box(400,430,320,'TARGET',money(p.target),'#45d2aa');box(752,430,320,'QUANTITY',`${Number(p.qty||0)} shares`,'#f2f6fc');c.fillStyle='#899bb2';c.font='17px Segoe UI, Arial';c.fillText(`${new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})} IST  ·  ALERT ONLY — NO ORDER PLACED`,48,625);canvas.toBlob(blob=>{if(!blob)return reject(Error('Could not encode Telegram alert image.'));if(blob.size>5_000_000)return reject(Error('Telegram alert image exceeded 5 MB.'));const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read Telegram alert image.'));reader.readAsDataURL(blob);},'image/png');});}
async function notifyTelegramEntryZone(p,previousCmp){
 const insideZone=distance(p)<=2,crossedDownZone=p.entry>0&&Number.isFinite(previousCmp)&&previousCmp>p.entry*1.02&&p.cmp<p.entry*0.98;
 if(!['Watching','Live watching','Live armed','Armed'].includes(p.status)||!(p.entry>0&&p.cmp>0)||(!insideZone&&!crossedDownZone)||p.telegramEntryAlertSentAt||telegramEntryAlertsInFlight.has(p.id))return;
 const last=Date.parse(p.telegramEntryAlertAttemptAt||'');if(Number.isFinite(last)&&Date.now()-last<5*60_000)return;
 telegramEntryAlertsInFlight.add(p.id);p.telegramEntryAlertAttemptAt=new Date().toISOString();save();
 const esc=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
 const caption=`<b>ENTRY ZONE ALERT · ${esc(p.symbol)}</b>\n${insideZone?'CMP is within 2% of planned Entry.':'CMP crossed the 2% approach zone between quote checks.'}\n<b>Setup:</b> ${esc(p.setup||'—')} · <b>Execution:</b> ${esc(p.timeframe||'—')}\n<b>CMP:</b> ${money(p.cmp)} · <b>Entry:</b> ${money(p.entry)}\n<b>SL:</b> ${money(p.sl)} · <b>Target:</b> ${money(p.target)}\n<b>Quantity:</b> ${Number(p.qty||0)} shares${p.notes?`\n<b>Note:</b> ${esc(p.notes).slice(0,240)}`:''}\n\n<i>Price alert only. No order placed by this notification.</i>`;
 try{const image=await entryZoneAlertImage(p,crossedDownZone),response=await fetch('/api/telegram/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({caption,image,filename:`${String(p.symbol||'trade').replace(/[^A-Z0-9_-]/gi,'_')}-entry-zone.png`}),signal:AbortSignal.timeout(30000)}),result=await response.json().catch(()=>({error:'Telegram returned an invalid response.'}));if(!response.ok)throw Error(result.error||'Telegram alert failed.');p.telegramEntryAlertSentAt=new Date().toISOString();p.telegramEntryAlertMessageId=result.messageId||'';p.telegramEntryAlertError='';save();toast(`${p.symbol}: Telegram entry-zone alert sent.`);}catch(error){p.telegramEntryAlertError=String(error.message||'Telegram alert failed.').slice(0,240);save();toast(`${p.symbol}: entry-zone Telegram alert failed — ${p.telegramEntryAlertError}`);}finally{telegramEntryAlertsInFlight.delete(p.id);}
}
function evaluate(p){if(p.status==='Armed'&&!state.paused&&p.enabled!==false&&!togglingPlans.has(p.id)){if(expired(p)){p.status='Watching';toast(`${p.symbol}: plan expired; disarmed.`);return;}if(p.cmp>=p.entry){const gap=(p.cmp/p.entry-1)*100;if(gap>state.settings.gap||p.cmp>=p.target){p.status='Watching';toast(`${p.symbol}: entry skipped beyond gap allowance.`);return;}const others=positions().filter(x=>x.id!==p.id),cost=others.reduce((s,x)=>s+x.qty*(x.fill||x.entry),0);if(cost+p.qty*p.cmp>state.settings.capital){p.status='Watching';toast(`${p.symbol}: fill blocked by available capital.`);return;}p.status='Holding';p.fill=p.cmp;p.filledAt=new Date().toISOString();toast(`${p.symbol}: simulated buy filled at ${money(p.fill)}.`);}}if(p.status==='Holding'&&(p.cmp<=p.sl||p.cmp>=p.target)){p.status=p.cmp<=p.sl?'SL hit':'Target hit';p.exit=p.cmp;p.exitSource='Paper';p.closedAt=new Date().toISOString();toast(`${p.symbol}: simulated ${p.status.toLowerCase()} at ${money(p.exit)}.`);}}
