 setLiveRecords(records){let changed=false;const labels={ARMED:'Live watching',ENTRY_PENDING:'Live entry pending',SUBMITTING:'Live submitting',UNKNOWN:'Live action required',ACTION_REQUIRED:'Live action required',PART_FILLED:'Live partial fill',PROTECTED:'Live holding',EXIT_TRIGGERED:'Live exit pending',CLOSED:'Closed',REJECTED:'Live rejected',CANCELLED:'Live cancelled',EXPIRED:'Live expired',DISARMED:'Watching'};for(const record of records){let p=state.plans.find(p=>p.id===record.tradeId);if(!p){p={id:record.tradeId,symbol:record.symbol,setup:record.setup,timeframe:record.timeframe||'Daily',notes:record.notes||'',expiry:record.expiry||'',cmp:null,cmpSource:'Awaiting Dhan',source:'Dhan live',targetMode:'manual',brokerage:0};state.plans.push(p);}if(p.liveUpdatedAt===record.updatedAt&&!(record.state==='CLOSED'&&(!p.executedAt||!p.completedAt)))continue;Object.assign(p,{liveState:record.state,liveFilledQty:record.filledQty||0,liveUpdatedAt:record.updatedAt,liveAccount:record.account,status:labels[record.state]||'Live action required'});if(record.state!=='DISARMED'){Object.assign(p,{symbol:record.symbol,entry:record.entry,sl:record.sl,target:record.target,qty:record.quantity});if(record.averageFillPrice>0)p.fill=record.averageFillPrice;if(record.filledQty>0&&record.entryTradeAt)Object.assign(p,{executedAt:record.entryTradeAt,executedDateOnly:false,tradeDatesSource:'Dhan live order'});if(record.state==='CLOSED'){const exitIds=(record.brokerLegs||[]).map(leg=>leg.orderId).filter(Boolean),entryAt=record.entryTradeAt||p.executedAt||'',exitAt=record.exitTradeAt||record.closedAt||p.completedAt||'';Object.assign(p,{qty:record.closedQuantity,exit:record.exitPrice,exitSource:'Dhan execution',exitOrderId:exitIds[0]||p.exitOrderId||'',dhanEntryOrderId:record.orderId||p.dhanEntryOrderId||'',dhanExitOrderIds:exitIds,source:'Dhan live',executedAt:entryAt,completedAt:exitAt,closedAt:exitAt,executedDateOnly:false,closedDateOnly:false,tradeDatesSource:record.entryTradeAt||record.exitTradeAt?'Dhan order / trade history':p.tradeDatesSource||''});}}changed=true;}if(changed)save();},
 symbols:()=>[...new Set([...state.plans.map(p=>p.symbol),...(latestPortfolio?.holdings||[]).map(p=>p.symbol),...(latestPortfolio?.positions||[]).map(p=>p.symbol)])],
